var breakpoints = (function() {
    "use strict";

    function init(config) {
       core.init(config);
    }

    
    var core = {
        list: null,
        media: {},
        events: [],


        init: function(config){
            core.list=config;

            //listen for events change viewport
            window.addEventListener("resize", core.poll);
            window.addEventListener("orientationchange", core.poll);
            window.addEventListener("load", core.poll);
            window.addEventListener("fullscreenchange", core.poll);
        },

        //checks breakpoints is active or not
        active: function(query) {
            var min, max, operator, bp, mediaQuery, unit;

            if(!(query in core.media)) {
                
                if (query.startsWith(">=")){ operator= "gte"; bp=query.substr(2);}
                else if (query.startsWith("<=")){ operator= "lte"; bp=query.substr(2);}
                else if (query.startsWith(">")){ operator= "gt"; bp=query.substr(1);}
                else if (query.startsWith("<")){ operator= "lt"; bp=query.substr(1);}
                else if (query.startsWith("!")){ operator= "not"; bp=query.substr(1);}
                else { operator = "eq"; bp=query;}

                if (bp && bp in core.list) {
                    var i = core.list[bp];
                
                    //min max
                    if (Array.isArray(i)) {
                        min = parseInt(i[0]);
                        max = parseInt(i[1]);
                        unit = isNaN(min) ? i[1].substr(String(max).length) : i[0].substr(String(min).length);
                    }
                
                    //css media 
                     if (isNaN(min)) {
                        switch(operator) {
                            case "gte": mediaQuery = "screen"; break;
                            case "lte": mediaQuery = "screen and (max-width: " + max + unit + ")"; break;
                            case "gt":  mediaQuery = "screen and (min-width: " + (max + 1) + unit + ")"; break;
                            case "lt":  mediaQuery = "screen and (max-width: -1px)"; break;
                            case "not": mediaQuery = "screen and (min-width: " + (max + 1) + unit + ")"; break;
                            default:    mediaQuery = "screen and (max-width: " + max + unit + ")"; break;
                        }
                     } else if (isNaN(max)) {
                        switch(operator) {
                            case "gte": mediaQuery = "screen and (min-width: " + min + unit + ")"; break;
                            case "lte": mediaQuery = "screen"; break;
                            case "gt":  mediaQuery = "screen and (max-width: -1px)"; break;
                            case "lt":  mediaQuery = "screen and (max-width: " + (min - 1) + unit + ")"; break;
                            case "not": mediaQuery = "screen and (max-width: " + (min - 1) + unit + ")"; break;
                            default:    mediaQuery = "screen and (min-width: " + min + unit + ")"; break;
                        }
                     } else {
                        switch(operator) {
                            case "gte": mediaQuery = "screen and (min-width: " + min + unit + ")"; break;
                            case "lte": mediaQuery = "screen and (max-width: " + max + unit + ")"; break;
                            case "gt":  mediaQuery = "screen and (min-width: " + (max + 1) + unit + ")"; break;
                            case "lt":  mediaQuery = "screen and (max-width: " + (min - 1) + unit + ")"; break;
                            case "not": mediaQuery = "screen and (max-width: " + (min - 1) + unit + "), screen and (min-width: " + (max + 1) + unit + ")"; break;
                            default:    mediaQuery = "screen and (min-width: " + min + unit + ") and (max-width: " + max + unit + ")"; break;
                        }
                     }
                } else {
                    mediaQuery = "(" + i.charAt(0) +")" ? "screen and " +i : i;
                }

                core.media[query] = !!mediaQuery && mediaQuery;
            }

            return core.media[query] !== false && window.matchMedia(core.media[query]).matches;
        },

        //attach callback for a breakpoint
        on: function(query, handler) {
            core.events.push({ query: query, handler: handler, state: false });
            if (core.active(query)) handler();
        },

        //poll all events
        poll: function() {
            core.events.forEach(function(evt) {
                if (core.active(evt.query)) {
                    if (!evt.state) {
                        evt.state = true; 
                        evt.handler();     
                    }
                } else if (evt.state) {
                    evt.state = false;    
                }
            });
        }
    };

    // expose public functions
    init._ = core;
    init.on = function(query, handler) { core.on(query, handler); };
    init.active = function(query) { return core.active(query); };

    return init;

})();


(function(global, factory) {
    if (typeof define === "function" && define.amd) define([], factory);
    else if (typeof exports === "object") module.exports = factory();
    else global.breakpoints = factory();
})(this, function() { return breakpoints; });
